import {useEffect,useLayoutEffect,useState, type ReactNode} from 'react';
import {LayoutDashboard,ListChecks,CalendarDays,ChartNoAxesCombined,Flag,MessagesSquare,FileChartColumn,BrainCircuit,Settings,Bell,Plus,ArrowUpRight,ChevronRight,Check,Clock,LogOut,X,Upload,Download,Send,Lock,Search,GitBranch,Menu,ShieldCheck,Target,Activity,UsersRound} from 'lucide-react';

import {request,refreshCsrf} from './api';
import UserManagement from './UserManagement';
import type {Person,User,WorkAction,Meeting,Decision,Kpi,Gate,AlertRule,Notification,Dashboard,Snapshot,Report} from './types';
const phases=['Arranque','Diagnóstico','Desenhar a oferta','Pilotar','Lançar'];const priorities=['Pacote de produtos KPO/TX','Pricing por resultados','Eficiência no back-office','Talento para o KPO','Gate e transição da operação','Confiança e governança da IA'];
const nav=[['overview','Visão geral',LayoutDashboard],['actions','Plano de acção',ListChecks],['meetings','Reuniões',CalendarDays],['kpis','KPIs',ChartNoAxesCombined],['processes','Processos',GitBranch],['gate','Gate',Flag],['decisions','Decisões',MessagesSquare],['reports','Reporte à CE',FileChartColumn],['cto','Gabinete do CTO',BrainCircuit],['users','Utilizadores',UsersRound],['settings','Configurações',Settings]] as const;
const titles:Record<string,string>={overview:'Da visão à execução.',actions:'Compromissos com dono e prazo.',meetings:'Conversas que se tornam acções.',kpis:'Resultados, com evidência.',processes:'A eficiência começa por dentro.',gate:'Prontidão para o lançamento.',decisions:'Decidir para desbloquear.',reports:'O essencial, numa página.',cto:'O teu gabinete de transformação.',users:'Gestão de utilizadores.',settings:'A plataforma, à tua medida.'};
const fmt=(d:string,opts?:Intl.DateTimeFormatOptions)=>new Date(d.length===10?d+'T12:00:00Z':d).toLocaleDateString('pt-PT',{timeZone:'Africa/Luanda',day:'2-digit',month:'short',year:'numeric',...opts});
const moment=(d:string)=>new Date(d).toLocaleString('pt-PT',{timeZone:'Africa/Luanda',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Luanda',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const state=(a:WorkAction)=>a.status!=='Concluída'&&a.dueDate<today()?'Atrasada':a.status;
const number=(n:number)=>n.toLocaleString('pt-PT',{maximumFractionDigits:1});
function Badge({children}:{children:ReactNode}){const text=String(children);return <span className={'badge '+(text==='Concluída'||text==='Confirmado'?'green':text==='Em curso'?'amber':text==='Em risco'||text==='Atrasada'?'red':'')}>{children}</span>}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Panel({title,extra,children,className=''}:{title:string;extra?:ReactNode;children:ReactNode;className?:string}){return <section className={'panel '+className}><div className="panel-head"><h2>{title}</h2>{extra}</div>{children}</section>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){useEffect(()=>{const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',handler);const previous=document.activeElement as HTMLElement;const d=document.querySelector<HTMLDialogElement>('#editor');d?.showModal();return()=>{document.removeEventListener('keydown',handler);previous?.focus()};},[]);return <dialog id="editor" className="modal" onCancel={e=>{e.preventDefault();onClose()}}><div className="modal-title"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Fechar"><X/></button></div>{children}</dialog>}
type Data={people:Person[];actions:WorkAction[];meetings:Meeting[];decisions:Decision[];kpis:Kpi[];gate:Gate[];notifications:Notification[];reports:Report[];dashboard:Dashboard|null};
const empty:Data={people:[],actions:[],meetings:[],decisions:[],kpis:[],gate:[],notifications:[],reports:[],dashboard:null};
export default function App(){
 const [user,setUser]=useState<User|null>(null),[boot,setBoot]=useState(false),[ready,setReady]=useState(false),[data,setData]=useState<Data>(empty),[page,setPage]=useState(()=>{const route=window.location.hash.slice(1);return nav.some(([key])=>key===route)?route:'overview'}),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[menu,setMenu]=useState(false),[alerts,setAlerts]=useState(false);
 const [action,setAction]=useState<WorkAction|null>(null),[deadlineReason,setDeadlineReason]=useState(''),[comments,setComments]=useState<{author:string;text:string;at:string}[]>([]),[comment,setComment]=useState(''),[subtask,setSubtask]=useState('');
 const [meeting,setMeeting]=useState<Meeting|null>(null),[decision,setDecision]=useState<Partial<Decision>|null>(null),[outcome,setOutcome]=useState(''),[measure,setMeasure]=useState<Kpi|null>(null),[measureForm,setMeasureForm]=useState({value:'',measuredOn:today(),source:'',comment:''});
 const [filters,setFilters]=useState({phase:'',owner:'',state:'',query:''}),[settings,setSettings]=useState<{values:Record<string,string>;openAiKeyConfigured:boolean;smtpPasswordConfigured:boolean;rules:AlertRule[]}|null>(null),[secrets,setSecrets]=useState({key:'',password:''});
 const [notes,setNotes]=useState<{id:string;text:string;at:string}[]>([]),[note,setNote]=useState(''),[question,setQuestion]=useState(''),[turns,setTurns]=useState<{id:string;question:string;answer:string;at:string}[]>([]),[summary,setSummary]=useState(''),[report,setReport]=useState<Snapshot|null>(null),[reportTitle,setReportTitle]=useState(''),[reportSummary,setReportSummary]=useState(''),[month,setMonth]=useState(today().slice(0,7));
 const [processes,setProcesses]=useState<any[]>([]),[processForm,setProcessForm]=useState<any>(null),[users,setUsers]=useState<any[]>([]),[newUser,setNewUser]=useState({personId:'',email:'',password:'',role:'officer'}),[gateDecision,setGateDecision]=useState<string|null>(null);
 const [settingsTab,setSettingsTab]=useState('email'),[smtpResult,setSmtpResult]=useState<{ok:boolean;message:string}|null>(null);
 useLayoutEffect(()=>{window.scrollTo({top:0,left:0,behavior:'instant'});document.querySelector('main')?.scrollTo(0,0);},[page]);
 const leader=!!user?.roles.includes('leader')&&user.personId==='paulo',ce=!!user?.roles.includes('ce');const canEdit=(a:WorkAction)=>leader||!ce&&(a.ownerId===user?.personId||a.participants.split(',').includes(user?.personId||''));
 const person=(id:string)=>data.people.find(p=>p.id===id)?.name||id;const owners=(p:string)=>p.split(',').filter(Boolean).map(person).join(' · ');
 async function run(task:()=>Promise<void>){setBusy(true);try{await task();}catch(e){setToast(e instanceof Error?e.message:'Ocorreu um erro.');}finally{setBusy(false);}}
 async function load(){const paths=['people','actions','meetings','decisions','kpis','gate','notifications','reports','dashboard'];const result=await Promise.all(paths.map(p=>request('/'+p)));const next=Object.fromEntries(paths.map((p,i)=>[p,result[i]])) as Data;setData(next);return next;}
 async function session(){await refreshCsrf();const s=await request<{required:boolean}>('/setup');setBoot(s.required);if(!s.required){try{const u=await request<User>('/me');setUser(u);await load();}catch{setUser(null)}}setReady(true);}
 useEffect(()=>{session().catch(e=>{setToast(e.message);setReady(true)})},[]);
 useEffect(()=>{if(!user)return;if(page==='settings')run(async()=>{setSettings(await request('/cto/settings'))});if(page==='cto')run(async()=>{setNotes(await request('/cto/notes'));setTurns(await request('/cto/advisor/history'));setSettings(await request('/cto/settings'))});if(page==='processes')run(async()=>setProcesses(await request('/processes')));if(page==='gate')run(async()=>setGateDecision((await request<{decision:string|null}>('/gate/decision')).decision));},[page,user?.id]);
 useEffect(()=>{if(!user)return;const timer=setInterval(()=>{load().catch(()=>{})},60000);return()=>clearInterval(timer);},[user?.id]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),9000);return()=>clearTimeout(timer)},[toast]);
 function navigate(p:string){setPage(p);window.history.replaceState(null,'','#'+p);setMenu(false);setAlerts(false);}
 async function openAction(a:WorkAction){setAction({...a});setDeadlineReason('');setComment('');setSubtask('');setComments(await request('/actions/'+a.id+'/comments'));}
 function newAction(meetingId:string|null=null){setComments([]);setDeadlineReason('');setAction({id:'',mandateNumber:null,title:'',description:'',phase:'Arranque',priority:1,ownerId:'paulo',participants:'paulo',dueDate:today(),originalDueDate:today(),deadlineLabel:'',deliverable:'',status:'Por iniciar',progress:0,version:1,updatedAt:new Date().toISOString(),completedAt:null,meetingId,dependsOnId:null,kpiId:null,evidence:[],history:[],subtasks:[]});}
 async function upload(type:string,id:string,file:File){const body=new FormData();body.append('file',file);await request('/evidence/'+type+'/'+id,'POST',body);const d=await load();if(action?.id===id)setAction(d.actions.find(a=>a.id===id)!);setToast('Evidência anexada.');}
 function updateAction(field:string,value:unknown){setAction(a=>a?{...a,[field]:value}:a)}
 async function saveAction(){if(!action)return;await request('/actions'+(action.id?'/'+action.id:''),action.id?'PUT':'POST',{...action,deadlineReason});await load();setAction(null);setToast('Acção gravada.');}
 async function exportReport(saved?:Report,privateMode=false){if(saved){setReport(JSON.parse(saved.snapshot));setReportTitle('Reporte à CE · '+saved.month);setReportSummary(saved.executiveSummary)}else{setReport(await request('/reports/preview'));setReportTitle(privateMode?'Apresentação à Sócia · '+fmt(today()):'Reporte à CE · '+month);setReportSummary(privateMode?summary:'')} }
 if(!ready)return <div className="loading">A abrir a transformação UCALL…</div>;
 if(!user)return <div className="login"><div className="login-art"><img src="/logo.png" alt="UCALL"/><span className="eyebrow">HORIZONTE 2027</span><h1>A próxima era<br/>da UCALL.</h1><p>KPO · TX · Inovação</p><InnovationArt/><span className="login-foot">Confidencial · Equipa de Transformação</span></div><div className="login-form"><span className="eyebrow">TRANSFORMATION OFFICE</span><h2>{boot?'Configuração inicial':'Bem-vindo de volta.'}</h2><p>{boot?'Cria a conta privada de Paulo Tavares.':'Entra para acompanhar e fazer avançar o plano.'}</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(async()=>{await request(boot?'/setup':'/login','POST',{email:f.get('email'),password:f.get('password'),token:f.get('token')});await session()})}}>{boot&&<Field label="Código de instalação"><input type="password" name="token" required autoComplete="off"/></Field>}<Field label="E-mail"><input type="email" name="email" autoComplete="username" required/></Field><Field label={boot?'Password (mínimo 12 caracteres)':'Password'}><input type="password" name="password" autoComplete={boot?'new-password':'current-password'} required minLength={boot?12:undefined}/></Field><button className="primary" disabled={busy}>{busy?'A verificar…':boot?'Criar conta':'Entrar'}<ArrowUpRight size={18}/></button></form>{toast&&<p className="error" role="alert">{toast}</p>}<p className="fine">O acesso é individual. As permissões são verificadas no servidor.</p></div></div>;
 const d=data.dashboard;
 return <div className="app"><aside className={menu?'sidebar open':'sidebar'}><div className="logo-wrap"><img src="/logo.png" alt="UCALL"/></div><span className="brand-caption">TRANSFORMAÇÃO</span><nav aria-label="Navegação principal">{nav.filter(([p])=>leader||!['cto','settings','users'].includes(p)).map(([p,label,Icon])=><button key={p} className={page===p?'selected':''} onClick={()=>navigate(p)}><Icon size={18}/><span>{label}</span>{p==='cto'&&<Lock size={12}/>}</button>)}</nav><div className="sidebar-foot"><span>Horizonte 2027</span><p>KPO · TX · Inovação</p><small>Confidencial · uso interno</small></div></aside><div className="workspace"><header className="topbar"><button className="icon-button menu-button" onClick={()=>setMenu(!menu)} aria-label="Abrir menu"><Menu/></button><div><span className="eyebrow">TRANSFORMAÇÃO UCALL / HORIZONTE 2027</span><p>{fmt(today())} · {d?.phase}</p></div><div className="top-actions"><button className="icon-button notification-button" onClick={()=>setAlerts(!alerts)} aria-label="Alertas"><Bell size={20}/>{data.notifications.some(n=>!n.read)&&<span className="notification-dot"/>}</button><div className="profile"><span className="avatar">{user.displayName.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('')}</span><div><strong>{user.displayName}</strong><small>{leader?'Chief Transformation Officer':user.roles.join(' · ')}</small></div></div><button className="icon-button" aria-label="Sair" onClick={()=>run(async()=>{await request('/logout','POST',{});setUser(null);setData(empty);await refreshCsrf()})}><LogOut size={18}/></button></div></header><main className={page==='overview'?'overview-page':''}><div className="page-heading"><div><h1>{titles[page]}</h1><p>{page==='cto'?'Privado · a tua análise, prioridades e preparação para a Sócia.':'KPO · TX · Inovação'}</p></div><div className="heading-actions">{page==='actions'&&leader&&<button className="primary" onClick={()=>newAction()}><Plus size={17}/>Nova acção</button>}{page==='meetings'&&leader&&<button className="primary" onClick={()=>setMeeting({id:'',title:'',scheduledAt:new Date().toISOString(),participants:'paulo,milton,ines,aniceto',agenda:'',minutes:'',mandateAccepted:false})}><Plus size={17}/>Nova reunião</button>}{page==='decisions'&&!ce&&<button className="primary" onClick={()=>{setDecision({request:'',toPersonId:'paulo',meetingId:null});setOutcome('')}}><Plus size={17}/>Pedir decisão</button>}{page==='overview'&&<button className="secondary" onClick={()=>navigate('reports')}><FileChartColumn size={17}/>Reporte à CE</button>}</div></div>
 {page==='overview'&&d&&<><section className="strategic"><div className="strategic-story"><InnovationArt/><div className="strategic-title"><h1>Da visão à execução<span>.</span></h1><p>KPO · TX · Inovação</p></div></div><div className="gate-ring"><div className="gate-progress" style={{'--progress':d.gateConfirmed/6*100+'%'} as React.CSSProperties}><strong>{d.gateConfirmed}<span>/6</span></strong><small>critérios confirmados</small></div></div><div className="countdown"><strong>{d.daysToGate}<span> dias</span></strong><p>Gate · 30 Set 2027</p><Badge>{d.phase}</Badge></div></section><div className="metric-strip"><Metric icon={<Activity/>} label="Em curso" value={d.counts['Em curso']||0} tone="amber"/><Metric icon={<Clock/>} label="Por iniciar" value={d.counts['Por iniciar']||0}/><Metric icon={<Check/>} label="Concluídas" value={d.counts['Concluída']||0} tone="green"/><Metric icon={<Target/>} label="No prazo · meta ≥90%" value={d.onTime===null?'Por apurar':number(d.onTime)+'%'}/></div><div className="overview-grid"><Panel className="roadmap-panel" title="O caminho para o lançamento" extra={<span className="fine">25 acções do mandato</span>}><Roadmap actions={data.actions} onSelect={a=>run(()=>openAction(a))}/></Panel><div className="attention-rail"><Panel className="week-panel" title="Esta semana" extra={<Badge>{d.overdue.length?'Atenção':'Foco'}</Badge>}>{[...d.overdue,...d.upcoming].slice(0,3).map(a=><button className="attention-item" key={a.id} onClick={()=>run(()=>openAction(a))}><span className="date-block"><b>{new Date(a.dueDate).getDate()}</b>{new Date(a.dueDate).toLocaleDateString('pt-PT',{month:'short'})}</span><span><strong>{a.title}</strong><small>{person(a.ownerId)}</small><Badge>{state(a)}</Badge></span></button>)}{!d.upcoming.length&&!d.overdue.length&&<p className="empty">Sem acções a vencer nos próximos 14 dias.</p>}<div className="micro-stats"><span>{d.overdue.length} atrasadas</span><span>{d.decisionsOver3} decisões &gt;3 dias</span></div></Panel><Panel className="focus-panel" title="Foco da semana" extra={<BrainCircuit size={17}/>}><p className="fine">O assessor privado analisa o plano, as dependências e os dados registados.</p>{leader?<button className="text-button" onClick={()=>{navigate('cto');setQuestion('Onde devo concentrar-me esta semana? Identifica os três principais pontos de intervenção com referências.')}}>Analisar com o meu assessor<ArrowUpRight size={16}/></button>:<p className="fine">Cada responsável actualiza as suas acções até segunda, fim do dia.</p>}</Panel></div></div><Panel className="priority-panel" title="Seis prioridades. Uma transformação." extra={<button className="text-button" onClick={()=>navigate('actions')}>Ver plano<ArrowUpRight size={15}/></button>}><div className="priority-grid">{priorities.map((p,i)=>{const item=d.priorities.find(x=>x.number===i+1);return <button className="priority-card" key={p} onClick={()=>{setFilters({phase:'',owner:'',state:'',query:''});navigate('actions')}}><span className="priority-number">P{i+1}<span className={'status-dot '+(item?.risk?'red':item?.active?'amber':'')}/></span><h3>{p}</h3><small>{item?.total?`${item.completed}/${item.total} concluídas`:'Sem acções associadas'}</small><div className="progress-track"><span style={{width:(item?.total?item.completed/item.total*100:0)+'%'}}/></div></button>})}</div></Panel><Panel className="impact-panel" title="Impacto a medir" extra={<button className="text-button" onClick={()=>navigate('kpis')}>Ver 7 KPIs<ArrowUpRight size={15}/></button>}><div className="impact-grid">{data.kpis.slice(0,3).map(k=><div key={k.id}><strong>{k.name}</strong><p>{k.value===null?'Sem baseline':number(k.value)+k.unit}</p><span className="impact-target">Meta {k.target}{k.unit}</span></div>)}</div></Panel>{d.additionalActions>0&&<p className="fine">Existem ainda {d.additionalActions} acções adicionais. O indicador de cumprimento do mandato usa exclusivamente as 25 acções originais.</p>}</>}
 {page==='actions'&&<Panel title="Plano de acção" extra={<Badge>{data.actions.length} acções</Badge>}><div className="filters"><label className="search"><Search size={17}/><input aria-label="Pesquisar acções" placeholder="Pesquisar acção ou entregável" value={filters.query} onChange={e=>setFilters({...filters,query:e.target.value})}/></label><select aria-label="Fase" value={filters.phase} onChange={e=>setFilters({...filters,phase:e.target.value})}><option value="">Todas as fases</option>{phases.map(p=><option key={p}>{p}</option>)}</select><select aria-label="Dono" value={filters.owner} onChange={e=>setFilters({...filters,owner:e.target.value})}><option value="">Todos os donos</option>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select aria-label="Estado" value={filters.state} onChange={e=>setFilters({...filters,state:e.target.value})}><option value="">Todos os estados</option>{['Por iniciar','Em curso','Em risco','Concluída','Atrasada'].map(p=><option key={p}>{p}</option>)}</select></div><div className="action-list">{data.actions.filter(a=>(!filters.phase||a.phase===filters.phase)&&(!filters.owner||a.participants.split(',').includes(filters.owner)||a.ownerId===filters.owner)&&(!filters.state||state(a)===filters.state)&&(!filters.query||`${a.title} ${a.deliverable}`.toLowerCase().includes(filters.query.toLowerCase()))).map(a=><button className="action-row" key={a.id} onClick={()=>run(()=>openAction(a))}><span className="action-number">{a.mandateNumber?String(a.mandateNumber).padStart(2,'0'):'+'}</span><span className="action-name"><strong>{a.title}</strong><small>{person(a.ownerId)} · {a.phase} · P{a.priority}</small>{a.deadlineLabel&&<small>{a.deadlineLabel}</small>}</span><span className="action-date">{fmt(a.dueDate)}</span><span><Badge>{state(a)}</Badge></span><span className="action-progress"><small>{a.progress}%</small><span className="progress-track"><span style={{width:a.progress+'%'}}/></span></span><ChevronRight size={16}/></button>)}</div></Panel>}
 {page==='meetings'&&<div className="meeting-grid">{data.meetings.map(m=><Panel key={m.id} title={m.title} extra={<CalendarDays size={18}/>}><p className="meeting-date">{moment(m.scheduledAt)} · Angola</p><p className="fine">{owners(m.participants)}</p><div className="meeting-agenda">{m.agenda.split('\n').map((line,i)=><p key={i}><span>{i+1}</span>{line}</p>)}</div><Badge>{m.mandateAccepted?'Mandato aceite':'Aceitação por definir'}</Badge>{m.minutes&&<p className="minutes-preview">{m.minutes}</p>}<div className="button-row">{leader&&<><button className="secondary" onClick={()=>setMeeting({...m})}>Abrir reunião</button><button className="text-button" onClick={()=>newAction(m.id)}><Plus size={16}/>Acção</button><button className="text-button" onClick={()=>{setDecision({request:'',toPersonId:'paulo',meetingId:m.id});setOutcome('')}}><Plus size={16}/>Decisão</button></>}</div></Panel>)}</div>}
 {page==='kpis'&&<><div className="kpi-guidance"><div><h2>Actualização directa pelos responsáveis</h2><p>Cada dono regista o valor, a data, a fonte e a evidência na plataforma. Os indicadores de automação, optimização e cumprimento de prazos são calculados a partir dos registos.</p></div><span className="badge">7 indicadores · uma fonte de verdade</span></div><div className="kpi-grid">{data.kpis.map(k=><Panel key={k.id} title={k.name} extra={<Badge>{k.calculated?'Calculado pela plataforma':'Registado pelo dono'}</Badge>}><div className="kpi-value"><strong>{k.value===null?'Sem baseline':number(k.value)}{k.value!==null&&<small>{k.unit}</small>}</strong><span>Meta <b>{k.target===null?'A fixar no Gate':number(k.target)+' '+k.unit}</b></span></div><p className="fine">Responsável: <strong>{person(k.ownerId)}</strong> · Prazo: {fmt(k.targetDate)}</p>{k.interimTarget!==null&&<p className="fine">Marco intermédio: {k.interimTarget}{k.unit} a {fmt(k.interimDate!)}</p>}<KpiChart kpi={k}/>{k.calculated?<div className="calculation"><p className="fine">{k.code==='ontime'?'Concluídas no prazo original ÷ acções do mandato já vencidas ou concluídas.':k.code==='automated'?'Processos internos automatizados ÷ processos internos validados.':'Processos mapeados optimizados ÷ processos mapeados validados.'}</p><button className="text-button" onClick={()=>navigate(k.code==='ontime'?'actions':'processes')}>{k.code==='ontime'?'Consultar acções que sustentam o indicador':'Consultar / actualizar processos'}<ArrowUpRight size={15}/></button></div>:<div className="measurement-list">{k.measurements.slice().sort((a,b)=>b.measuredOn.localeCompare(a.measuredOn)).slice(0,4).map(m=><div key={m.id}><span>{fmt(m.measuredOn)} · {number(m.value)} {k.unit}</span><small>Fonte: {m.source}</small>{m.comment&&<small>{m.comment}</small>}{m.evidence.map(e=><a key={e.id} href={'/api/evidence/'+e.id}>{e.name}</a>)}{(leader||user.personId===k.ownerId)&&<label className="text-button upload-button">Anexar evidência<input type="file" onChange={e=>{const f=e.target.files?.[0];if(f)run(()=>upload('measurement',m.id,f));e.target.value=''}}/></label>}</div>)}</div>}{!k.calculated&&(leader||!ce&&user.personId===k.ownerId)&&<button className="primary" onClick={()=>{setMeasure(k);setMeasureForm({value:'',measuredOn:today(),source:'',comment:''})}}><Plus size={16}/>Actualizar indicador</button>}{k.code==='revenue'&&leader&&<button className="text-button" onClick={()=>{const v=prompt('Meta de receita tecnológica em AKZ:',String(k.target||''));if(v!==null&&v.trim()&&Number.isFinite(Number(v)))run(async()=>{await request('/kpis/'+k.id+'/target','PUT',{target:Number(v)});await load()})}}>Definir meta no Gate</button>}</Panel>)}</div></>}
 {page==='processes'&&<Panel title="Inventário validado de processos" extra={leader||['ines','aniceto'].includes(user.personId)?<button className="primary" onClick={()=>setProcessForm({name:'',ownerId:'ines',internal:true,mapped:false,automated:false,optimized:false,evidence:'',verifiedOn:today()})}><Plus size={16}/>Registar processo</button>:null}><p className="fine">Este inventário alimenta os KPIs calculados. Fonte e data de validação são obrigatórias. Cada processo deve ser registado uma única vez.</p>{!processes.length&&<div className="empty">Ainda não existe baseline de processos. Regista o inventário validado antes de interpretar percentagens.</div>}{processes.map(p=><div className="process-row" key={p.id}><strong>{p.name}</strong><span>{person(p.ownerId)}</span><Badge>{p.automated?'Automatizado':p.optimized?'Optimizado':p.mapped?'Mapeado':'Por mapear'}</Badge><small>Fonte: {p.evidence} · {fmt(p.verifiedOn)}</small></div>)}</Panel>}
 {page==='gate'&&<><section className="gate-banner"><div><span className="eyebrow">30 SETEMBRO 2027</span><h2>Seis critérios.<br/>Uma decisão formal.</h2><p>Sem todos os critérios cumpridos, a automação facturada não arranca.</p></div><div className="gate-progress"><strong>{data.gate.filter(g=>g.confirmed).length}<span>/6</span></strong><small>confirmados</small></div></section><Panel title="Critérios de lançamento">{data.gate.map(g=><div className="gate-row" key={g.id}><span className={'criterion-icon '+(g.confirmed?'confirmed':'')}>{g.confirmed?<Check size={19}/>:g.number}</span><div><strong>{g.title}</strong><small>{person(g.ownerId)} · {fmt(g.dueDate)}</small><div>{g.evidence.map(e=><a key={e.id} href={'/api/evidence/'+e.id}>{e.name}</a>)}</div></div><div className="gate-row-actions"><Badge>{g.confirmed?'Confirmado':'Por validar'}</Badge>{(leader||!ce&&g.ownerId===user.personId)&&<label className="text-button upload-button"><Upload size={15}/>Evidência<input type="file" onChange={e=>{const f=e.target.files?.[0];if(f)run(()=>upload('gate',g.id,f));e.target.value=''}}/></label>}{(leader||ce)&&<button className="secondary" disabled={busy||!g.evidence.length} onClick={()=>run(async()=>{await request('/gate/'+g.id,'PUT',{confirmed:!g.confirmed});await load()})}>{g.confirmed?'Reabrir':'Confirmar'}</button>}</div></div>)}<p className="fine">Se algum critério falhar, o Gate repete-se no trimestre seguinte. A aprovação formal é uma permissão específica da CE.</p>{gateDecision?<div className="detail-callout">Decisão registada: {gateDecisionText(gateDecision)}</div>:ce&&<button className="primary" disabled={data.gate.some(g=>!g.confirmed)||busy} onClick={()=>{const text=prompt('Regista a decisão formal da CE e as condições de lançamento:');if(text)run(async()=>{await request('/gate/launch','POST',{text});setGateDecision((await request<{decision:string|null}>('/gate/decision')).decision)})}}>Registar decisão de lançamento</button>}</Panel></>}
 {page==='decisions'&&<Panel title="Pedidos e decisões" extra={<Badge>{data.decisions.filter(d=>!d.decidedAt).length} pendentes</Badge>}>{!data.decisions.length&&<div className="empty"><MessagesSquare/><h3>A primeira decisão começa na reunião.</h3><p>Regista o pedido, o destinatário e o resultado. O alerta surge ao ultrapassar três dias corridos.</p></div>}{data.decisions.map(d=>{const days=Math.floor(((d.decidedAt?new Date(d.decidedAt):new Date()).getTime()-new Date(d.requestedAt).getTime())/86400000);return <button className="decision-row" key={d.id} onClick={()=>{setDecision(d);setOutcome(d.outcome)}}><div><strong>{d.request}</strong><small>Para {person(d.toPersonId)} · {fmt(d.requestedAt)}</small>{d.outcome&&<p>{d.outcome}</p>}</div><Badge>{d.decidedAt?'Decidida':days>3?'Atrasada':'Pendente'}</Badge><span>{days} dias</span><ChevronRight size={16}/></button>})}</Panel>}
 {page==='reports'&&<><Panel title="Reporte mensal à Comissão Executiva" extra={<FileChartColumn size={20}/>}><p className="fine">O arquivo guarda uma fotografia dos dados. Os meses já fechados não mudam com actualizações futuras.</p><div className="report-controls"><Field label="Mês"><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></Field><Field label="Síntese executiva"><textarea value={summary} onChange={e=>setSummary(e.target.value)} placeholder="Avanços, riscos prioritários e decisões pedidas"/></Field></div><div className="button-row"><button className="secondary" onClick={()=>run(async()=>{await exportReport();setReportSummary(summary)})}>Pré-visualizar / PDF</button>{leader&&<button className="primary" disabled={busy} onClick={()=>run(async()=>{await request('/reports','POST',{month,executiveSummary:summary});await load();setToast('Reporte mensal arquivado.');})}>Fechar e arquivar mês</button>}</div></Panel><Panel title="Arquivo mensal">{!data.reports.length?<p className="empty">Ainda não existem reportes fechados.</p>:data.reports.map(r=><button key={r.id} className="report-row" onClick={()=>run(()=>exportReport(r))}><FileChartColumn size={18}/><strong>{r.month}</strong><span>Guardado a {fmt(r.createdAt)}</span><Download size={17}/></button>)}</Panel></>}
 {page==='cto'&&leader&&<><section className="cto-hero"><div><span className="eyebrow"><Lock size={13}/> APENAS PAULO TAVARES</span><h2>Clareza para liderar.<br/>Evidência para decidir.</h2><p>Um assessor que acompanha a execução e prepara a tua intervenção.</p></div><BrainCircuit size={90} strokeWidth={1}/></section><div className="cto-grid"><Panel title="Assessor IA" extra={<Badge>{settings?.openAiKeyConfigured?'Configurado':'Chave por configurar'}</Badge>}><div className="suggested-prompts">{['Onde estamos a falhar?','Onde devo incidir esta semana?','O que pode comprometer o Gate?','O que devo levar à Paula?'].map(p=><button key={p} onClick={()=>setQuestion(p)}>{p}<ArrowUpRight size={13}/></button>)}</div>{!settings?.openAiKeyConfigured&&<p className="detail-callout">Insere a chave da OpenAI em Configurações. A análise usa dados da aplicação e distingue factos de hipóteses.</p>}<div className="chat-history">{turns.slice().reverse().map(t=><article key={t.id}><p className="chat-question">{t.question}</p><div className="chat-answer">{t.answer}</div><small>{moment(t.at)}</small></article>)}</div><form className="chat-form" onSubmit={e=>{e.preventDefault();run(async()=>{const result=await request<{answer:string}>('/cto/advisor','POST',{text:question});setTurns([{id:crypto.randomUUID(),question,answer:result.answer,at:new Date().toISOString()},...turns]);setQuestion('')})}}><textarea aria-label="Pergunta ao assessor" placeholder="O que precisas de perceber ou preparar?" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={3000}/><button className="primary" disabled={busy||!question.trim()||!settings?.openAiKeyConfigured}><Send size={17}/>{busy?'A analisar…':'Perguntar'}</button></form><p className="fine">A análise não altera registos nem envia mensagens. Confirma as propostas antes de agir.</p></Panel><div><Panel title="Notas privadas" extra={<Lock size={16}/>}><textarea aria-label="Nova nota privada" value={note} onChange={e=>setNote(e.target.value)} placeholder="Notas para a tua preparação. Não entram no reporte nem no contexto da IA."/><button className="secondary" disabled={busy||!note.trim()} onClick={()=>run(async()=>{await request('/cto/notes','POST',{text:note});setNotes(await request('/cto/notes'));setNote('')})}>Guardar nota</button>{notes.map(n=><div className="private-note" key={n.id}><p>{n.text}</p><small>{fmt(n.at)}</small></div>)}</Panel><Panel title="Apresentar à Sócia" extra={<FileChartColumn size={17}/>}><p className="fine">Resultados demonstrados, bloqueios e pedidos de decisão. As notas privadas ficam excluídas.</p><Field label="Pontos seleccionados para apresentação"><textarea value={summary} onChange={e=>setSummary(e.target.value)} placeholder="Escreve ou adapta a síntese do assessor."/></Field><button className="primary" onClick={()=>run(()=>exportReport(undefined,true))}>Preparar apresentação</button></Panel></div></div></>}
 {page==='settings'&&leader&&<><div className="settings-tabs" role="tablist" aria-label="Configurações">{[['email','E-mail / SMTP'],['alerts','Alertas'],['ai','Assessor / OpenAI']].map(([id,label],index)=><button key={id} id={'tab-'+id} role="tab" aria-selected={settingsTab===id} aria-controls={'settings-'+id} tabIndex={settingsTab===id?0:-1} onClick={()=>setSettingsTab(id)} onKeyDown={e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const ids=['email','alerts','ai'];const next=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;setSettingsTab(ids[next]);document.getElementById('tab-'+ids[next])?.focus()}}}>{label}</button>)}</div>{!settings?<div className="empty">A carregar configurações…</div>:<div role="tabpanel" id={'settings-'+settingsTab} aria-labelledby={'tab-'+settingsTab}>{settingsTab==='ai'&&<Panel title="OpenAI · assessor privado" extra={<Lock size={17}/>}><p className="fine">A chave é cifrada no servidor e nunca devolvida ao browser. Uma caixa vazia preserva a chave existente.</p><Field label={settings.openAiKeyConfigured?'Chave configurada · substituir':'Chave da OpenAI'}><input type="password" autoComplete="off" value={secrets.key} onChange={e=>setSecrets({...secrets,key:e.target.value})} placeholder="Insere a chave aqui"/></Field><Field label="Modelo"><input value={settings.values['openai.model']||''} onChange={e=>setSettings({...settings,values:{...settings.values,'openai.model':e.target.value}})}/></Field><div className="button-row"><button className="primary" disabled={busy} onClick={()=>run(async()=>{await request('/cto/settings','PUT',{values:{'openai.key':secrets.key,'openai.model':settings.values['openai.model']}});setSecrets({...secrets,key:''});setSettings(await request('/cto/settings'));setToast('Configuração OpenAI guardada.');})}>Guardar OpenAI</button>{settings.openAiKeyConfigured&&<button className="text-button danger" onClick={()=>{if(confirm('Remover a chave da OpenAI?'))run(async()=>{await request('/cto/settings/openai-key','DELETE');setSettings(await request('/cto/settings'))})}}>Remover chave</button>}</div></Panel>}{settingsTab==='email'&&<Panel title="Ligação ao servidor de e-mail">{[['smtp.host','Servidor'],['smtp.port','Porta'],['smtp.user','Utilizador'],['smtp.from','Remetente'],['app.publicUrl','Endereço da aplicação']].map(([key,label])=><Field key={key} label={label}><input value={settings.values[key]||''} onChange={e=>setSettings({...settings,values:{...settings.values,[key]:e.target.value}})}/></Field>)}<Field label="Password SMTP"><input type="password" autoComplete="off" value={secrets.password} placeholder={settings.smtpPasswordConfigured?'Configurada · vazio para manter':'Password'} onChange={e=>setSecrets({...secrets,password:e.target.value})}/></Field><label className="checkbox"><input type="checkbox" checked={settings.values['smtp.tls']!=='false'} onChange={e=>setSettings({...settings,values:{...settings.values,'smtp.tls':String(e.target.checked)}})}/>Ligação TLS (STARTTLS)</label><div className="form-grid"><Field label="Modo de envio"><select value={settings.values['email.mode']||'instant'} onChange={e=>setSettings({...settings,values:{...settings.values,'email.mode':e.target.value}})}><option value="instant">Imediato após horário da regra</option><option value="daily">Resumo diário</option><option value="weekly">Resumo semanal (terça)</option></select></Field><Field label="Hora do resumo · Angola"><input type="number" min="0" max="23" value={settings.values['email.hour']||'9'} onChange={e=>setSettings({...settings,values:{...settings.values,'email.hour':e.target.value}})}/></Field></div><button className="primary" disabled={busy} onClick={()=>run(async()=>{const values=Object.fromEntries(Object.entries(settings.values).filter(([k])=>k.startsWith('smtp.')||k.startsWith('email.')||k==='app.publicUrl'));await request('/cto/settings','PUT',{values:{...values,'email.mode':values['email.mode']||'instant','email.hour':values['email.hour']||'9','smtp.password':secrets.password}});setSecrets({...secrets,password:''});setSettings(await request('/cto/settings'));setToast('Configuração de e-mail guardada.');})}>Guardar e-mail</button><div className="smtp-test"><h3>Testar o envio</h3><p className="fine">Guarda primeiro a configuração. O teste envia um email para a tua conta: <strong>{user.email}</strong>.</p><button className="secondary" disabled={busy} onClick={()=>run(async()=>{setSmtpResult(null);try{const result=await request<{message:string}>('/cto/settings/smtp-test','POST',{});setSmtpResult({ok:true,message:result.message})}catch(e){setSmtpResult({ok:false,message:e instanceof Error?e.message:'Não foi possível enviar o teste.'})}})}><Send size={16}/>{busy?'A testar…':'Enviar email de teste'}</button>{smtpResult&&<p role="status" className={smtpResult.ok?'smtp-success':'error'}>{smtpResult.message}</p>}</div></Panel>}{settingsTab==='alerts'&&<Panel title="Alertas e antecedência" extra={<Bell size={18}/>}><p className="fine">Avisos na plataforma são gerados a cada cinco minutos. E-mail só é enviado com SMTP configurado e a opção da regra activa.</p><div className="alert-rules">{settings.rules.map(r=><div className="alert-rule" key={r.id}><div className="rule-title"><h3>{r.label}</h3><label className="checkbox"><input type="checkbox" checked={r.enabled} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,enabled:e.target.checked}:x)})}/>Activo</label></div><div className="rule-fields">{['deadline','gate'].includes(r.kind)&&<Field label="Dias antes (ex.: 7,3,1)"><input value={r.daysBefore} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,daysBefore:e.target.value}:x)})}/></Field>}<Field label="Repetir a cada (dias)"><input type="number" min="1" value={r.repeatEveryDays} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,repeatEveryDays:Number(e.target.value)}:x)})}/></Field><Field label="Escalar após (dias)"><input type="number" min="1" value={r.escalateAfterDays} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,escalateAfterDays:Number(e.target.value)}:x)})}/></Field><Field label="Destinatários"><select value={r.recipients} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,recipients:e.target.value}:x)})}><option value="owner">Responsável</option><option value="owner,participants">Responsável e participantes</option><option value="owner,leader">Responsável e Paulo</option><option value="leader">Apenas Paulo</option></select></Field><Field label="Hora · Angola"><input type="number" min="0" max="23" value={r.sendHour} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,sendHour:Number(e.target.value)}:x)})}/></Field></div><div className="button-row"><label className="checkbox"><input type="checkbox" checked={r.email} onChange={e=>setSettings({...settings,rules:settings.rules.map(x=>x.id===r.id?{...x,email:e.target.checked}:x)})}/>Enviar por e-mail</label><button className="secondary" disabled={busy} onClick={()=>run(async()=>{await request('/cto/alerts/'+r.id,'PUT',r);setToast('Regra guardada.');})}>Guardar regra</button></div></div>)}</div></Panel>}</div>}</>}
 {page==='users'&&leader&&<UserManagement people={data.people} currentUser={user} onDirectoryUpdated={load}/> }
 </main><footer>UCALL · Equipa de Transformação · Actualizações até segunda ao fim do dia.</footer></div>
 {alerts&&<div className="notifications-panel"><div className="panel-head"><h2>Alertas</h2><button className="icon-button" onClick={()=>setAlerts(false)} aria-label="Fechar alertas"><X/></button></div>{!data.notifications.length&&<p className="empty">Sem alertas registados.</p>}{data.notifications.map(n=><button key={n.id} className={'notification-item '+(n.read?'read':'')} onClick={()=>run(async()=>{await request('/notifications/'+n.id+'/read','PUT',{});await load();navigate(n.link)})}><strong>{n.title}</strong><small>{moment(n.createdAt)} · {n.emailStatus}</small></button>)}</div>}
 {toast&&<div className="toast" role="alert">{toast}<button aria-label="Fechar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}
 {action&&<Modal title={action.id?`Acção ${action.mandateNumber||'adicional'}`:'Nova acção'} onClose={()=>setAction(null)}><form onSubmit={e=>{e.preventDefault();run(saveAction)}}><div className="form-grid"><Field label="Título"><input required value={action.title} disabled={!leader} onChange={e=>updateAction('title',e.target.value)}/></Field><Field label="Entregável"><input required value={action.deliverable} disabled={!leader} onChange={e=>updateAction('deliverable',e.target.value)}/></Field><Field label="Responsável principal"><select value={action.ownerId} disabled={!leader} onChange={e=>updateAction('ownerId',e.target.value)}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Participantes"><select multiple value={action.participants.split(',')} disabled={!leader} onChange={e=>updateAction('participants',Array.from(e.target.selectedOptions).map(o=>o.value).join(','))}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Prazo"><input type="date" required value={action.dueDate} disabled={!leader} onChange={e=>updateAction('dueDate',e.target.value)}/></Field><Field label="Motivo de alteração de prazo"><input value={deadlineReason} disabled={!leader} onChange={e=>setDeadlineReason(e.target.value)} placeholder="Obrigatório ao alterar"/></Field><Field label="Fase"><select value={action.phase} disabled={!leader} onChange={e=>updateAction('phase',e.target.value)}>{phases.map(p=><option key={p}>{p}</option>)}</select></Field><Field label="Prioridade estratégica"><select value={action.priority} disabled={!leader} onChange={e=>updateAction('priority',Number(e.target.value))}>{priorities.map((p,i)=><option key={p} value={i+1}>P{i+1} · {p}</option>)}</select></Field><Field label="Estado"><select value={action.status} disabled={!canEdit(action)} onChange={e=>updateAction('status',e.target.value)}>{['Por iniciar','Em curso','Em risco','Concluída'].map(p=><option key={p}>{p}</option>)}</select></Field><Field label="Avanço (%)"><input type="number" min="0" max="100" value={action.progress} disabled={!canEdit(action)} onChange={e=>updateAction('progress',Number(e.target.value))}/></Field><Field label="Depende da acção"><select value={action.dependsOnId||''} disabled={!leader} onChange={e=>updateAction('dependsOnId',e.target.value||null)}><option value="">Sem dependência</option>{data.actions.filter(a=>a.id!==action.id).map(a=><option key={a.id} value={a.id}>{a.mandateNumber||'+'} · {a.title}</option>)}</select></Field><Field label="KPI associado"><select value={action.kpiId||''} disabled={!leader} onChange={e=>updateAction('kpiId',e.target.value||null)}><option value="">Sem KPI</option>{data.kpis.map(k=><option key={k.id} value={k.id}>{k.name}</option>)}</select></Field><Field label="Reunião de origem"><select value={action.meetingId||''} disabled={!leader} onChange={e=>updateAction('meetingId',e.target.value||null)}><option value="">Sem reunião</option>{data.meetings.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select></Field></div><Field label="Descrição / ponto de situação"><textarea value={action.description} disabled={!canEdit(action)} onChange={e=>updateAction('description',e.target.value)}/></Field>{action.deadlineLabel&&<p className="fine">{action.deadlineLabel}</p>}{canEdit(action)&&<button className="primary" disabled={busy}>Guardar acção</button>}</form>{action.id&&<><hr/><h3>Evidências</h3>{action.evidence.map(e=><a className="evidence-link" key={e.id} href={'/api/evidence/'+e.id}><Download size={15}/>{e.name}</a>)}{canEdit(action)&&<label className="secondary upload-button"><Upload size={16}/>Anexar evidência<input type="file" accept=".pdf,.png,.jpg,.jpeg,.docx,.xlsx,.csv,.txt" onChange={e=>{const f=e.target.files?.[0];if(f)run(()=>upload('action',action.id,f));e.target.value=''}}/></label>}<p className="fine">Conclusão exige pelo menos uma evidência. Máximo 20 MB por ficheiro.</p><hr/><h3>Sub-tarefas</h3>{action.subtasks.map(s=><label className="checkbox" key={s.id}><input type="checkbox" checked={s.done} disabled={!canEdit(action)||busy} onChange={e=>run(async()=>{await request('/subtasks/'+s.id,'PUT',{title:s.title,done:e.target.checked});const d=await load();setAction(d.actions.find(a=>a.id===action.id)!);})}/>{s.title}</label>)}{canEdit(action)&&<form className="inline-form" onSubmit={e=>{e.preventDefault();run(async()=>{await request('/actions/'+action.id+'/subtasks','POST',{title:subtask,done:false});setSubtask('');const d=await load();setAction(d.actions.find(a=>a.id===action.id)!);})}}><input aria-label="Nova sub-tarefa" required value={subtask} onChange={e=>setSubtask(e.target.value)} placeholder="Nova sub-tarefa"/><button className="secondary" disabled={busy}><Plus size={16}/></button></form>}<hr/><h3>Comentários</h3>{comments.map((c,i)=><div className="comment" key={i}><strong>{person(c.author)}</strong><small>{moment(c.at)}</small><p>{c.text}</p></div>)}<form className="inline-form" onSubmit={e=>{e.preventDefault();run(async()=>{await request('/actions/'+action.id+'/comments','POST',{text:comment});setComment('');setComments(await request('/actions/'+action.id+'/comments'));})}}><input required aria-label="Comentário" value={comment} onChange={e=>setComment(e.target.value)} placeholder="Deixar comentário"/><button className="secondary" disabled={busy}><Send size={16}/></button></form><hr/><h3>Histórico e prazo original</h3><p className="fine">Prazo original: {fmt(action.originalDueDate)}</p>{action.history.slice().sort((a,b)=>b.at.localeCompare(a.at)).map(h=><div className="history" key={h.id}><p>{h.description}</p><small>{person(h.actor)} · {moment(h.at)}</small></div>)}</>}</Modal>}
 {meeting&&<Modal title="Reunião da equipa" onClose={()=>setMeeting(null)}><form onSubmit={e=>{e.preventDefault();run(async()=>{await request('/meetings'+(meeting.id?'/'+meeting.id:''),meeting.id?'PUT':'POST',meeting);await load();setMeeting(null);setToast('Reunião gravada.');})}}><Field label="Título"><input required value={meeting.title} onChange={e=>setMeeting({...meeting,title:e.target.value})}/></Field><Field label="Data e hora · Angola"><input type="datetime-local" required value={new Date(new Date(meeting.scheduledAt).getTime()+3600000).toISOString().slice(0,16)} onChange={e=>setMeeting({...meeting,scheduledAt:e.target.value+'+01:00'})}/></Field><Field label="Participantes"><select multiple value={meeting.participants.split(',')} onChange={e=>setMeeting({...meeting,participants:Array.from(e.target.selectedOptions).map(o=>o.value).join(',')})}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Agenda"><textarea value={meeting.agenda} onChange={e=>setMeeting({...meeting,agenda:e.target.value})}/></Field><Field label="Acta / decisões registadas"><textarea rows={7} value={meeting.minutes} onChange={e=>setMeeting({...meeting,minutes:e.target.value})}/></Field><label className="checkbox"><input type="checkbox" checked={meeting.mandateAccepted} onChange={e=>setMeeting({...meeting,mandateAccepted:e.target.checked})}/>Aceitação do mandato registada</label><p className="fine">A aceitação não conclui automaticamente a acção 1. Anexa a acta e confirma cadência e tempo protegido.</p><button className="primary" disabled={busy}>Guardar reunião</button></form></Modal>}
 {decision&&<Modal title={decision.id?'Decisão':'Pedir decisão'} onClose={()=>setDecision(null)}>{decision.id?<><h3>{decision.request}</h3><p className="fine">Para {person(decision.toPersonId||'')} · {fmt(decision.requestedAt!)}</p><Field label="Resultado / condições"><textarea value={outcome} disabled={!!decision.decidedAt} onChange={e=>setOutcome(e.target.value)}/></Field>{!decision.decidedAt&&(leader||decision.toPersonId===user.personId||ce&&decision.toPersonId==='ce')&&<button className="primary" disabled={busy||!outcome.trim()} onClick={()=>run(async()=>{await request('/decisions/'+decision.id,'PUT',{text:outcome});await load();setDecision(null);})}>Registar decisão</button>}</>:<form onSubmit={e=>{e.preventDefault();run(async()=>{await request('/decisions','POST',decision);await load();setDecision(null)})}}><Field label="O que é pedido"><textarea required value={decision.request||''} onChange={e=>setDecision({...decision,request:e.target.value})}/></Field><Field label="A quem"><select value={decision.toPersonId} onChange={e=>setDecision({...decision,toPersonId:e.target.value})}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><p className="fine">Alerta ao ultrapassar três dias corridos.</p><button className="primary" disabled={busy}>Registar pedido</button></form>}</Modal>}
 {measure&&<Modal title={'Registar · '+measure.name} onClose={()=>setMeasure(null)}><form onSubmit={e=>{e.preventDefault();run(async()=>{await request('/kpis/'+measure.id+'/measurements','POST',{...measureForm,value:Number(measureForm.value)});await load();setMeasure(null)})}}><div className="form-grid"><Field label={'Valor ('+measure.unit+')'}><input type="number" step="any" min="0" required value={measureForm.value} onChange={e=>setMeasureForm({...measureForm,value:e.target.value})}/></Field><Field label="Data da medição"><input type="date" required max={today()} value={measureForm.measuredOn} onChange={e=>setMeasureForm({...measureForm,measuredOn:e.target.value})}/></Field></div><Field label="Fonte"><input required value={measureForm.source} onChange={e=>setMeasureForm({...measureForm,source:e.target.value})}/></Field><Field label="Comentário"><textarea value={measureForm.comment} onChange={e=>setMeasureForm({...measureForm,comment:e.target.value})}/></Field><p className="fine">Depois de gravar, podes anexar a evidência à medição.</p><button className="primary" disabled={busy}>Guardar medição</button></form></Modal>}

 {processForm&&<Modal title="Registar processo validado" onClose={()=>setProcessForm(null)}><form onSubmit={e=>{e.preventDefault();run(async()=>{await request('/processes','POST',processForm);setProcesses(await request('/processes'));await load();setProcessForm(null)})}}><Field label="Nome"><input required value={processForm.name} onChange={e=>setProcessForm({...processForm,name:e.target.value})}/></Field><Field label="Responsável"><select value={processForm.ownerId} onChange={e=>setProcessForm({...processForm,ownerId:e.target.value})}>{data.people.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>{[['internal','Processo interno'],['mapped','Processo mapeado'],['automated','Automatizado'],['optimized','Optimizado']].map(([k,l])=><label className="checkbox" key={k}><input type="checkbox" checked={processForm[k]} onChange={e=>setProcessForm({...processForm,[k]:e.target.checked})}/>{l}</label>)}<Field label="Fonte / referência da evidência"><input required value={processForm.evidence} onChange={e=>setProcessForm({...processForm,evidence:e.target.value})}/></Field><Field label="Data de validação"><input type="date" required max={today()} value={processForm.verifiedOn} onChange={e=>setProcessForm({...processForm,verifiedOn:e.target.value})}/></Field><button className="primary" disabled={busy}>Guardar processo</button></form></Modal>}
 {report&&<Modal title={reportTitle} onClose={()=>setReport(null)}><div className="print-report"><div className="report-brand"><img src="/logo.png" alt="UCALL"/><div><h2>{reportTitle}</h2><small>{fmt(report.dashboard.today)} · Confidencial</small></div></div>{reportSummary&&<section><h3>Síntese executiva</h3><p>{reportSummary}</p></section>}<div className="report-metrics"><span><b>{report.dashboard.onTime===null?'Por apurar':report.dashboard.onTime+'%'}</b> no prazo</span><span><b>{report.dashboard.gateConfirmed}/6</b> Gate</span><span><b>{report.dashboard.overdue.length}</b> atrasadas</span></div><section><h3>Seis prioridades</h3><div className="report-priorities">{priorities.map((p,i)=>{const stat=report.dashboard.priorities.find(x=>x.number===i+1);return <p key={p}>P{i+1} · {p}: {stat?.completed||0}/{stat?.total||0} concluídas{stat?.risk?` · ${stat.risk} em risco/atrasadas`:''}</p>})}</div></section><section><h3>KPIs face às metas</h3><table><tbody>{report.kpis.map(k=><tr key={k.code}><td>{k.name}</td><td>{k.value===null?'Sem medição':number(k.value)} / {k.target===null?'A fixar':number(k.target)} {k.unit}</td></tr>)}</tbody></table></section><section><h3>Acções atrasadas e datas revistas</h3>{report.dashboard.overdue.length?report.dashboard.overdue.map(a=><p key={a.id}>{a.title} · data actual: {fmt(a.dueDate)} · original: {fmt(a.originalDueDate)}</p>):<p>Nenhuma acção atrasada.</p>}</section><section><h3>Decisões pendentes</h3>{report.decisions.filter(d=>!d.decidedAt).length?report.decisions.filter(d=>!d.decidedAt).map(d=><p key={d.id}>{d.request} · {person(d.toPersonId)}</p>):<p>Nenhuma registada.</p>}</section><section><h3>3 riscos de referência do mandato</h3>{report.risks.map(r=><p key={r}>{r}</p>)}</section><p className="fine">Estado dos dados à data de preparação. Notas privadas excluídas.</p></div><button className="primary no-print" onClick={()=>window.print()}><Download size={17}/>Imprimir / Guardar em PDF</button></Modal>}
 </div>
}
function Metric({icon,label,value,tone=''}:{icon:ReactNode;label:string;value:string|number;tone?:string}){return <div className="metric"><span className={'metric-icon '+tone}>{icon}</span><div><strong>{value}</strong><small>{label}</small></div></div>}
function InnovationArt(){return <svg className="innovation-art" viewBox="0 0 580 240" aria-hidden="true"><defs><linearGradient id="tx-glass" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#fff"/><stop offset="1" stopColor="#e1e5eb"/></linearGradient><linearGradient id="tx-core" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#ff8496" stopOpacity=".5"/><stop offset="1" stopColor="#d71934" stopOpacity=".9"/></linearGradient><radialGradient id="tx-node"><stop offset="0" stopColor="#ffc2ca"/><stop offset=".3" stopColor="#ef5269"/><stop offset="1" stopColor="#bc122b"/></radialGradient><linearGradient id="tx-fade"><stop stopColor="white"/><stop offset=".4" stopColor="white" stopOpacity=".8"/><stop offset="1" stopColor="white" stopOpacity="0"/></linearGradient><filter id="tx-shadow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="5"/></filter></defs><g fill="none" stroke="#d9dde5" strokeWidth="1"><path d="M65 180L190 112L336 178L463 110L566 158M130 35L190 112L320 40L463 110M190 112L215 223M336 178L385 217M463 110L510 20M336 178L320 40M65 180L130 35"/><path d="M190 112L463 110M336 178L510 20M190 112L566 158" stroke="#df334d" strokeDasharray="2 5"/></g><g opacity=".8"><path d="M95 177L139 154L184 177L139 201Z" fill="#ccd2dd" opacity=".2" filter="url(#tx-shadow)"/><path d="M95 171L139 148L184 171L139 193Z" fill="url(#tx-glass)" stroke="#fff"/><path d="M95 176L139 198L184 176" fill="none" stroke="#c9d0db"/><path d="M364 46L399 27L435 46L399 64Z" fill="url(#tx-glass)" stroke="#fff"/><path d="M364 51L399 70L435 51" fill="none" stroke="#c9d0db"/><path d="M454 164L501 137L548 164L501 190Z" fill="url(#tx-glass)" stroke="#fff"/><path d="M454 170L501 196L548 170" fill="none" stroke="#c9d0db"/></g><ellipse cx="327" cy="154" rx="73" ry="24" fill="#d71934" opacity=".14" filter="url(#tx-shadow)"/><g fill="none" stroke="#b6beca" strokeWidth="1"><path d="M251 139L327 180L403 139"/><path d="M251 133L327 174L403 133"/><path d="M251 127L327 168L403 127"/></g><path d="M251 118L327 77L403 118L327 160Z" fill="url(#tx-glass)" stroke="#f3f5f8"/><path d="M251 118V127L327 168L403 127V118L327 160Z" fill="#bcc4cf" opacity=".45"/><path d="M268 111L327 79L386 111L327 143Z" fill="url(#tx-core)" stroke="#f69baa"/><path d="M268 117L327 149L386 117" fill="none" stroke="#f2697e"/><path d="M275 105L327 77L379 105L327 133Z" fill="#fae5e9" fillOpacity=".65" stroke="#fff"/>{[[65,180],[130,35],[190,112],[336,178],[463,110],[510,20],[566,158],[215,223],[385,217],[327,102]].map(([x,y],i)=><g key={i}>{i%3===0?<><ellipse cx={x} cy={y+9} rx="10" ry="3" fill="#d71934" opacity=".12" filter="url(#tx-shadow)"/><circle cx={x} cy={y} r={i===9?7:6} fill="url(#tx-node)"/><circle cx={x-2} cy={y-2} r="1.6" fill="#fff" opacity=".8"/></>:<circle cx={x} cy={y} r="3" fill="#c5cbd5"/>}</g>)}<rect width="300" height="240" fill="url(#tx-fade)"/></svg>}
function Roadmap({actions,onSelect}:{actions:WorkAction[];onSelect:(a:WorkAction)=>void}){const start=new Date('2026-10-01').getTime(),end=new Date('2028-01-01').getTime();const pos=(date:string)=>Math.max(0,Math.min(100,(new Date(date).getTime()-start)/(end-start)*100));const gate=pos('2027-09-30'),now=pos(today());return <div className="roadmap"><div className="roadmap-years"><span>2026</span><span>2027</span></div><div className="roadmap-months"><span/>{['Out','Nov','Dez','Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'].map((m,i)=><span key={i}>{m}</span>)}</div>{phases.map(p=>{const list=actions.filter(a=>a.mandateNumber&&a.phase===p);const used:number[]=[];return <div className="roadmap-lane" key={p}><span>{p}</span><div className="lane-content"><span className="gate-marker" style={{left:gate+'%'}}/><span className="today-marker" style={{left:now+'%'}}/>{list.map(a=>{const x=pos(a.dueDate);const collision=used.filter(v=>Math.abs(v-x)<2.8).length;used.push(x);return <button key={a.id} onClick={()=>onSelect(a)} className={'milestone '+(a.status==='Em curso'?'running':a.status==='Concluída'?'done':a.mandateNumber===21?'gate':'')} style={{left:`min(${x}%, calc(100% - 8px))`,top:8+collision*15+'px'}} aria-label={`Acção ${a.mandateNumber}: ${a.title}. ${fmt(a.dueDate)}`} title={`${a.mandateNumber}. ${a.title} · ${fmt(a.dueDate)}`}>{a.mandateNumber}</button>})}</div></div>})}<div className="roadmap-legend"><span><i className="amber"/>Hoje · {fmt(today())}</span><span><i className="red"/>Gate · 30 Set 2027</span></div><p className="fine">Marcos por prazo. Outubro e Novembro de lançamento têm datas operacionais provisórias.</p></div>}
function KpiChart({kpi:k}:{kpi:Kpi}){const values=k.measurements.slice().sort((a,b)=>a.measuredOn.localeCompare(b.measuredOn));if(!values.length)return <div className="chart-empty">Histórico disponível após as primeiras medições.</div>;const first=values[0],start=new Date(first.measuredOn).getTime(),end=Math.max(new Date(k.targetDate).getTime(),...values.map(m=>new Date(m.measuredOn).getTime()));const max=Math.max(k.target||0,...values.map(m=>m.value),1)*1.1,x=(date:string)=>25+(new Date(date).getTime()-start)/Math.max(1,end-start)*310,y=(v:number)=>120-v/max*95;const points=values.map(m=>`${x(m.measuredOn)},${y(m.value)}`).join(' ');return <div className="kpi-chart"><svg viewBox="0 0 365 150" role="img" aria-label={`Histórico de ${k.name}; último valor ${values.at(-1)?.value}`}><path d="M25 20V120H340" fill="none" stroke="#d9dce3"/>{k.target!==null&&<><line x1="25" y1={y(k.target)} x2="340" y2={y(k.target)} stroke="#aeb3bf" strokeDasharray="3 5"/><text x="340" y={y(k.target)-6} textAnchor="end">Meta {k.target}</text></>}<polyline points={points} stroke="#d71934" strokeWidth="2" fill="none"/>{values.map(m=><circle key={m.id} cx={x(m.measuredOn)} cy={y(m.value)} r="4" fill="#d71934"><title>{fmt(m.measuredOn)} · {m.value} · {m.source}</title></circle>)}<text x="25" y="143">{fmt(first.measuredOn,{year:undefined})}</text><text x="340" y="143" textAnchor="end">{fmt(k.targetDate,{year:undefined})}</text></svg><p className="fine">Linha vermelha: valores medidos. Linha tracejada: meta. Trajectória preditiva ainda não validada.</p></div>}

function gateDecisionText(value:string){try{const parsed=JSON.parse(value);return typeof parsed?.decision==='string'?parsed.decision:value}catch{return value}}
